import heapq

def match(orders):
    trades = []
    buy_book = []   # heap of (-price, seq, id)
    sell_book = []  # heap of (price, seq, id)
    order_info = {}  # id -> dict with side, price, qty, seq, active
    seq_counter = 0

    def add_resting(order_id, side, price, qty, seq):
        if side == 'buy':
            heapq.heappush(buy_book, (-price, seq, order_id))
        else:
            heapq.heappush(sell_book, (price, seq, order_id))

    def clean_buy_top():
        while buy_book:
            negprice, seq, oid = buy_book[0]
            info = order_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_book)
            else:
                return True
        return False

    def clean_sell_top():
        while sell_book:
            price, seq, oid = sell_book[0]
            info = order_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_book)
            else:
                return True
        return False

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = order_info.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        order_info[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq_counter, 'active': True}
        my_seq = seq_counter
        seq_counter += 1

        if side == 'buy':
            while remaining > 0 and clean_sell_top():
                sprice, sseq, sid = sell_book[0]
                if typ != 'market' and price is not None and sprice > price:
                    break
                sinfo = order_info[sid]
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, sid, sprice, trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                if sinfo['qty'] <= 0:
                    heapq.heappop(sell_book)
                    sinfo['active'] = False
            order_info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                add_resting(oid, side, price, remaining, my_seq)
            else:
                order_info[oid]['active'] = False if remaining <= 0 or typ != 'limit' else True
                if typ != 'limit':
                    order_info[oid]['active'] = False

        else:  # sell
            while remaining > 0 and clean_buy_top():
                negprice, bseq, bid = buy_book[0]
                bprice = -negprice
                if typ != 'market' and price is not None and bprice < price:
                    break
                binfo = order_info[bid]
                trade_qty = min(remaining, binfo['qty'])
                trades.append([bid, oid, bprice, trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                if binfo['qty'] <= 0:
                    heapq.heappop(buy_book)
                    binfo['active'] = False
            order_info[oid]['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                add_resting(oid, side, price, remaining, my_seq)
            else:
                if typ != 'limit':
                    order_info[oid]['active'] = False

    return trades

